package com.supportsphere.service; import com.supportsphere.dao.*; import com.supportsphere.exception.*; import com.supportsphere.model.*; import java.time.*; import java.util.*; public class RequestService {private final RequestDAO dao=new RequestDAO(); public int create(AssistanceRequest r)throws Exception{if(r.getTaskType()==null||r.getTaskType().isBlank())throw new ValidationException("Choose a task category.");if(r.getDescription()==null||r.getDescription().isBlank())throw new ValidationException("Describe the assistance you need.");if(r.getArea()==null||r.getArea().isBlank()||r.getCity()==null||r.getCity().isBlank())throw new ValidationException("Area and city are required.");if(r.getPreferredDate()==null||r.getPreferredDate().isBefore(LocalDate.now()))throw new ValidationException("Choose today or a future date.");if(r.getStartTime()==null||r.getEndTime()==null||!r.getEndTime().isAfter(r.getStartTime()))throw new ValidationException("End time must be after start time.");if(r.getPreferredDate().equals(LocalDate.now())&&r.getEndTime().isBefore(LocalTime.now()))throw new ValidationException("The selected time has already passed today.");return dao.save(r);} public List<AssistanceRequest> mine(int id)throws Exception{return dao.findByRequester(id);} public List<AssistanceRequest> open()throws Exception{return dao.findOpen();} public List<AssistanceRequest> all()throws Exception{return dao.findAllRequests();} public AssistanceRequest get(int id)throws Exception{return dao.findById(id).orElseThrow();} public List<String> history(int id)throws Exception{return dao.history(id);} public void cancel(int id,int by,String reason)throws Exception{dao.cancel(id,by,reason);} }
